    expect(quotePremium(items, newcomer, 0)).toBe(236);
  });

  test('enchantment 5 adds the 30 % high-enchantment surcharge', () => {
    // 100 base + 30 enchantment = 130; +13 first insurance; +5 fee
    expect(quotePremium([{ type: 'sword', enchantment: 5 }], newcomer, 0)).toBe(148);
  });

  test('enchantment 4 adds no high-enchantment surcharge', () => {
    // 100 base; +10 first insurance; +5 fee
    expect(quotePremium([{ type: 'sword', enchantment: 4 }], newcomer, 0)).toBe(115);
  });

  test('a cursed sword with enchantment 5 gets both surcharges', () => {
    // 100 + 50 + 30 = 180; +18 first insurance; +5 fee
    expect(quotePremium([{ type: 'sword', cursed: true, enchantment: 5 }], newcomer, 0)).toBe(203);
  });
});

