import { type Item, insuranceSum } from './premium.js';

const DEDUCTIBLE = 100;

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
  remainingCap: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function createPolicy(items: Item[]): Policy {
  return { items, remainingCap: insuranceSum(items) * 2 };
}

export function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  let payout = 0;
  for (const damage of incident.damages) {
    payout += Math.max(0, damage.amount - DEDUCTIBLE);
  }
  return { payout, remainingCap: policy.remainingCap - payout };
}

